-- The SUMO-L-DRILL code key (Code keys -> Drilling -> SUMO-L-DRILL), from the ISCAR
-- e-catalog's SUMO-L-DRILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.sumoldrill', $ck${"title": "SUMO-L-DRILL code key – drilling heads and drill bodies", "subtitle": "Exchangeable drilling heads (ILP) with a side screw lock, and the DLN drill bodies for interrupted and unstable drilling", "example": "ILP 120-2M", "decoder": "sumo-l-drill", "sections": [{"key": "i-family", "title": "Head – family", "sample": "ILP", "rows": [{"code": "ILP", "meaning": "Drilling heads for DLN drills, for ISO P and ISO K materials"}]}, {"key": "i-dia", "title": "Head – drilling diameter", "sample": "120", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 120 = 12.0 mm)"}, {"code": "####", "meaning": "Drilling diameter x100 (e.g. 1588 = 15.88 mm)"}]}, {"key": "i-suffix", "title": "Head – suffix", "sample": "2M", "rows": [{"code": "2M", "meaning": "Double margin"}]}, {"key": "t-family", "title": "Drill body – family", "sample": "DLN", "rows": [{"code": "DLN", "meaning": "Exchangeable head drill body with a side screw lock system, for interrupted drilling"}]}, {"key": "t-dia", "title": "Drill body – head size", "rows": [{"code": "###", "meaning": "Smallest head diameter it carries x10 (e.g. 120 = 12.0 mm)"}]}, {"key": "t-length", "title": "Drill body – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-height", "title": "Drill body – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (16, 20, 25)"}]}, {"key": "t-shank", "title": "Drill body – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}]}, {"key": "t-depth", "title": "Drill body – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth as a ratio of the diameter (3D = 3xD, 5D = 5xD)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
